const payload = $json.body || $json;

const nvidiaBody = {
  model: 'nvidia/nemotron-3.5-lightning-30b-a3b',
  messages: [
    {
      role: 'system',
      content: 'You are an AI lead-qualification assistant for an enterprise Salesforce DevOps / release-governance vendor. Return ONLY valid JSON, no markdown. Use exactly these keys: fit_score (integer 1-10, how well this lead fits an enterprise Salesforce release/compliance buyer), route_to_human (boolean), urgency (one of: urgent, high, medium, low), pain_point (string), summary (one sentence), recommended_action (short phrase), confidence (number 0-1). Set route_to_human to true if the message describes a production outage, failed deployment, data loss, security issue, release blocker, audit/compliance pressure, or the person asks for immediate human help. Otherwise set it to false.'
    },
    {
      role: 'user',
      content: JSON.stringify(payload)
    }
  ],
  temperature: 0.1,
  top_p: 0.7,
  max_tokens: 1024,
  stream: false
};

return [{ json: nvidiaBody }];

const webhook = $('Webhook - Inbound Lead').item.json.body || $('Webhook - Inbound Lead').item.json;
const ai = $json;

// 1. Extract the raw model text
const raw = ai.choices?.[0]?.message?.content ?? ai.content?.[0]?.text ?? ai.output ?? '';
let cleaned = String(raw).trim();

// 2. Strip markdown fences and isolate the JSON object
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
const first = cleaned.indexOf('{');
const last = cleaned.lastIndexOf('}');
if (first !== -1 && last > first) cleaned = cleaned.slice(first, last + 1);
cleaned = cleaned.replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ');

// 3. Parse, with a safe fallback so the workflow never crashes
let parsed = {};
let parseWarning = false;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseWarning = true;
  const routeMatch = /"route_to_human"\s*:\s*(true|"true"|1)/i.test(raw);
  parsed = {
    route_to_human: routeMatch,
    urgency: routeMatch ? 'urgent' : 'low',
    pain_point: 'JSON parse warning',
    summary: 'Extracted via fallback parser',
    recommended_action: 'Review payload manually',
    confidence: 0.5
  };
}

// 4. Coerce route_to_human into a real boolean
let routeBool = false;
const r = parsed.route_to_human;
if (typeof r === 'boolean') routeBool = r;
else if (typeof r === 'string') routeBool = ['true', '1', 'yes', 'urgent'].includes(r.toLowerCase().trim());
else if (typeof r === 'number') routeBool = r === 1;

// 5. fit_score: integer 1-10 (falls back to confidence x 10)
let fit = Math.round(Number(parsed.fit_score));
if (!Number.isFinite(fit)) fit = Math.round(Number(parsed.confidence) * 10);
if (!Number.isFinite(fit)) fit = 5;
fit = Math.min(10, Math.max(1, fit));

// 6. Normalize contact and company fields (Day 4 payloads use company_name / contact_name)
const fullName = String(webhook.contact_name || '').trim();
const parts = fullName ? fullName.split(/\s+/) : [];
const firstName = webhook.firstName || (parts.length > 1 ? parts[0] : '');
const lastName = webhook.lastName || (parts.length > 1 ? parts.slice(1).join(' ') : (parts[0] || 'Lead'));
const company = webhook.company_name || webhook.company || 'Demo Company';

return [{
  json: {
    ...webhook,
    ...parsed,
    route_to_human: routeBool,
    route_decision: routeBool ? 'urgent' : 'nurture',
    fit_score: fit,
    firstName,
    lastName,
    company,
    contact_name: fullName || (firstName + ' ' + lastName).trim(),
    email: webhook.email || '',
    parse_warning: parseWarning,
    _raw_ai_response: raw
  }
}];

